SELECT *
FROM tms_fx


        AND trade_number LIKE CONCAT('%', #{req.tradeNumber}, '%')


        AND (ccy1 = #{req.currency} OR ccy2 = #{req.currency})


        AND (ccy1_amount >= #{req.amountMin} OR ccy2_amount >= #{req.amountMin})


        AND (ccy1_amount <= #{req.amountMax} OR ccy2_amount <= #{req.amountMax})


        AND value_date >= #{req.valueDateStart}


        AND value_date <= #{req.valueDateEnd}


        AND payment_status = #{req.paymentStatus}


ORDER BY sort_id DESC
